fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn px(cx: i32, i: i32, rr: i32) -> i32 {
    cx + sv(i * 4) * rr / 127
}

fn py(cy: i32, i: i32, rr: i32) -> i32 {
    cy - sv(i * 4 + 8) * rr / 127
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 2 - 30 } else { h / 2 - 30 };
    let scores = [80, 55, 90, 40, 70, 65, 85, 50];
    host::display::clear(0x08080c);
    let mut i: i32 = 0;
    while i < 8 {
        let j: i32 = (i + 1) & 7;
        host::display::draw_line(cx, cy, px(cx, i, r), py(cy, i, r), 0x28282f);
        host::display::draw_line(px(cx, i, r / 2), py(cy, i, r / 2), px(cx, j, r / 2), py(cy, j, r / 2), 0x30303a);
        host::display::draw_line(px(cx, i, r), py(cy, i, r), px(cx, j, r), py(cy, j, r), 0x40404c);
        i = i + 1;
    }
    i = 0;
    while i < 8 {
        let j: i32 = (i + 1) & 7;
        let ri: i32 = r * scores[i] / 100;
        let rj: i32 = r * scores[j] / 100;
        host::display::draw_line(px(cx, i, ri), py(cy, i, ri), px(cx, j, rj), py(cy, j, rj), 0x40ff90);
        host::display::fill_rect(px(cx, i, ri) - 2, py(cy, i, ri) - 2, 5, 5, 0xffffff);
        i = i + 1;
    }
    host::display::draw_string(8, 8, "SKILL RADAR", 0x808080, 1);
    host::display::present();
}
